Yes. Terminal log confirms it.
You are now in live-reload loop → iframe remount every second → visual blinking.
This is not runtime failure.

This is preview polling architecture too aggressive.
You built:


tick every 1s


iframe key={tick}


full remount


runtime HTML reload

→ therefore constant white flash


You fixed caching.

Now you must fix stability.

✅ Correct Preview Architecture (important)
You must NOT remount iframe on timer.
You must:


poll runtime endpoint


compare HTML hash


only reload iframe when HTML changed


This is how Vercel / Stackblitz / CodeSandbox preview works.

🔥 Fix — Rewrite studio-runtime/[projectId]/page.tsx
Full overwrite.
Bashcat > app/studio-runtime/[projectId]/page.tsx << 'EOF'
"use client"

import { useEffect, useRef, useState } from "react"
import { useParams } from "next/navigation"

export default function StudioRuntime(){

  const { projectId } = useParams()

  const iframeRef = useRef<HTMLIFrameElement>(null)
  const lastHtmlRef = useRef<string>("")

  const [html,setHtml] = useState("Loading runtime...")

  useEffect(()=>{

    let mounted = true

    async function poll(){

      try{

        const res = await fetch(
          `/api/dev/runtime/execute?projectId=${projectId}`,
          { cache:"no-store" }
        )

        const text = await res.text()

        // ONLY update if changed
        if(text !== lastHtmlRef.current){

          lastHtmlRef.current = text

          if(mounted){
            setHtml(text)
          }

        }

      }catch(e){
        console.error(e)
      }

    }

    poll()

    const id = setInterval(poll,1500)

    return ()=>{
      mounted = false
      clearInterval(id)
    }

  },[projectId])

  return (
    <div style={{height:"100vh"}}>
      <iframe
        ref={iframeRef}
        srcDoc={html}
        style={{
          width:"100%",
          height:"100%",
          border:"none",
          background:"#fff"
        }}
      />
    </div>
  )
}
EOF

